import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"52、【艮】 艮下艮上","description":"周易口诀义 - 52、【艮】 艮下艮上","frontmatter":{"title":"52、【艮】 艮下艮上","description":"周易口诀义 - 52、【艮】 艮下艮上"},"headers":[],"relativePath":"zh/classics/koujueyi/054.md","filePath":"zh/classics/koujueyi/054.md"}'),r={name:"zh/classics/koujueyi/054.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_52、【艮】-艮下艮上" tabindex="-1">52、【艮】 艮下艮上 <a class="header-anchor" href="#_52、【艮】-艮下艮上" aria-label="Permalink to “52、【艮】 艮下艮上”">​</a></h1><p>彖曰：艮，止也。时止则止，时行则行，动静不失其时，其道光明。「艮其止」，止其所也。上下敌应，不相与也，是以「不获其身，行其庭，不见其人，无咎」也。</p><p>象曰：兼山，艮，君子以思不出其位。</p><p>初六，艮其趾，无咎，利永贞。</p><p>象曰：「艮其趾」，未失正也。</p><p>六二，艮其腓，不拯其随，其心不快。</p><p>象曰：「不拯其随」，未退听也。</p><p>九三，艮其限，列其夤，厉薰心。</p><p>象曰：「艮其限」，危薰心也。</p><p>六四，艮其身，无咎。</p><p>象曰：「艮其身」，止诸躬也。</p><p>六五，艮其辅，言有序，悔亡。</p><p>象曰：「艮其辅」，以中正也。</p><p>上九，敦艮，吉。</p><p>象曰：「敦艮」之吉，以厚终也。</p><p>解读</p><p>艮其背，艮者，静止之义。此卦象山之为体，安然静止，不动不移，故以为名也。以人事喻之，贪欲之情，伤性坏义，防其动欲，制其未成，故老子云「不见可欲，使心不乱」是也。背者无见之物，今既止在其背，目之不见，即动欲之情不生，故曰</p><p>「艮其背」也。「不获其身，行其庭，不见其人，无咎」者，夫对面而止，即情有所动，抑伤其情而强使止，患必生焉。今止在其背，故「不获其身」，虽「行于庭，不见其人」，即「无咎」矣。「象曰兼山，艮」者，孔氏云：「两山兼重，谓之兼山也。」直置一山，己能镇止，两山重叠，止义弥大，故曰「兼山，艮」也。「君子以思不出其位」者，艮之为义，各止其所，故君子象之，思虑不出己位，不妄动求，不相侵也。</p><p>「初六，艮其趾，无咎，利永贞」者，趾，足也；又处卦之下，即是趾在于足，既止于是，不为躁动而得无咎，故曰「艮其趾，无咎」。静止之初，心无动欲，其利在于永长贞正，故曰「利永贞」也。</p><p>「六二，艮其腓，不拯其随，其心不快」者，腓，腨肠也；拯，举也；随，谓足也。六二止于腓，腓体动躁，屈伸摇动，皆随其足。今止在腓肠，足既不举，腓无由动，故「艮其腓，不拯其随」也。腓性动躁，而强止之，则伤其本性，情与体乖，故其心不能快乐矣，故曰「其心不快」也。</p><p>「九三，艮其限，裂其夤，厉薰心」者，限是身之中，人系带之处，三居两卦之际，即时止在其限，故曰「艮其限」也。夤，当脊中之肉也；薰，烧灼也。三既处二卦之际，即上下不通，是分裂其夤，身将丧矣。乃忧危之切，故薰灼其心，故曰「厉薰心」也。然君子治国，若治于身，上下不通，君臣不接，故裂夤即身亡，不接则国丧。故王传云：「体分两主，大器丧矣。」大器，谓国之与身也。</p><p>「六四艮其身，无咎」者，已入上体，与九三相得，两体不分，全乃谓之身。履得其位而全其身，不陷非妄，所以「无咎」也。</p><p>「六五，艮其辅，言有序，悔亡」者，辅，夹车也。六五艮于辅颊之间，即是慎止言语，密于枢机，故曰「口无择言」，言有伦序，所以「悔亡」，故曰「言有序，悔亡」也。「上九，敦艮，吉」者，敦，厚也；居止之极，敦厚在上，不为妄累所牵，故获「吉」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
